operations.schema:
input SetUsernameInput {
  "Add your inputs here"
  username: String!
}

input SetEthAddressInput {
  "Add your inputs here"
  ethAddress: EthereumAddress!
}

input SetUserImageInput {
  "Add your inputs here"
  userImage: String!
}

input SetDisplayNameInput {
  "1-64 characters after trimming; null clears"
  displayName: String
}

input SetHandleInput {
  "^[a-z0-9](?:[a-z0-9-]{1,28}[a-z0-9])$; null clears"
  handle: String
}

input SetBioInput {
  "At most 280 characters; null or empty clears"
  bio: String
}

input SetAvatarInput {
  "attachment://v1:<sha256>; null clears"
  avatar: AttachmentRef
}

input UpdateLinkInput {
  id: OID!
  label: String
  url: URL
}
